<?php use App\Models\Ticket; $groups=[]; foreach($tickets as $t) { $g=match($filters['group']??''){'team'=>$t['team_name']??'Sans équipe','assignee'=>$t['assignee_name']??'Non assigné','priority'=>Ticket::PRIORITIES[$t['priority']],'type'=>Ticket::TYPES[$t['type']],'parent'=>$t['parent_id']?'Parent #'.$t['parent_id']:'Sans parent','labels'=>implode(', ',$t['labels_array'])?:'Sans étiquette',default=>''}; $groups[$g][]=$t; } if(!$groups) $groups=[''=>[]]; ?>
<?php if($count>1000): ?><div class="notice">Les 1 000 premiers tickets sont affichés. Affinez les filtres pour examiner les suivants.</div><?php endif; ?>
<?php foreach($groups as $groupName=>$groupTickets): ?><?php if($groupName): ?><h2 class="board-group-title"><?= e($groupName) ?><span><?= count($groupTickets) ?></span></h2><?php endif; ?><div class="kanban-board"><?php foreach(Ticket::STATUSES as $state=>$label): $cards=array_filter($groupTickets,fn($t)=>$t['status']===$state); ?><section class="kanban-column" data-drop-status="<?= e($state) ?>"><header class="column-header"><span class="legend-dot status-<?= e($state) ?>"></span><h2><?= e($label) ?></h2><span class="column-count"><?= count($cards) ?></span><button class="icon-button" data-collapse-column aria-label="Réduire <?= e($label) ?>"><?= icon('down') ?></button></header><div class="column-cards"><?php foreach($cards as $t): ?><article class="ticket-card <?= $t['flagged']?'flagged-card':'' ?>" draggable="<?= $user['role']==='viewer'?'false':'true' ?>" data-ticket-id="<?= (int)$t['id'] ?>" data-version="<?= (int)$t['version'] ?>" data-priority="<?= e($t['priority']) ?>" data-status="<?= e($t['status']) ?>" data-type="<?= e($t['type']) ?>" data-flagged="<?= (int)$t['flagged'] ?>" data-completed="<?= e($t['completed_at']) ?>"><div class="card-top"><span class="ticket-key"><?= e($t['key']) ?></span><details class="dropdown align-right"><summary class="tiny-button" aria-label="Actions pour <?= e($t['key']) ?>"><?= icon('more') ?></summary><div class="dropdown-menu"><a href="/tickets/<?= (int)$t['id'] ?>">Ouvrir et modifier</a><button data-copy="<?= e(url('/tickets/'.$t['id'])) ?>">Copier le lien</button><button data-copy="<?= e($t['key']) ?>">Copier la clé</button><a href="/tickets/<?= (int)$t['id'] ?>#relations">Relations et parent</a><form method="post" action="/tickets/<?= (int)$t['id'] ?>/archive"><?= csrf() ?><button data-confirm="Archiver ce ticket ? Vous pourrez le restaurer depuis sa fiche.">Archiver</button></form></div></details></div><a class="card-title" href="/tickets/<?= (int)$t['id'] ?>"><?= e($t['title']) ?></a><?php if($t['team_name']): ?><span class="pill soft card-team"><?= e($t['team_name']) ?></span><?php endif; ?><div class="card-labels"><?php foreach(array_slice($t['labels_array'],0,3) as $tag): ?><span class="label-tag"><?= e($tag) ?></span><?php endforeach; ?></div><?php if($t['due_date']): ?><div class="card-due <?= $t['due_date']<gmdate('Y-m-d')&&$state!=='done'?'overdue':'' ?>"><?= icon('clock') ?><?= e((new DateTimeImmutable($t['due_date']))->format('d M')) ?></div><?php endif; ?><footer class="card-footer"><span class="type-icon type-<?= e($t['type']) ?>"><?= ['task'=>'✓','story'=>'▮','bug'=>'•','subtask'=>'⊡','epic'=>'ϟ'][$t['type']] ?></span><span class="priority-mark priority-<?= e($t['priority']) ?>" title="<?= e(Ticket::PRIORITIES[$t['priority']]) ?>">≋</span><?php if($t['flagged']): ?><span class="blocked-flag"><?= icon('flag') ?></span><?php endif; ?><span class="toolbar-spacer"></span><?= avatar($t['assignee_name'],'small', $t['assignee_id'] ? (int)$t['assignee_id'] : null) ?></footer></article><?php endforeach; ?></div><button class="column-create" data-create-status="<?= e($state) ?>"><?= icon('plus') ?>Créer un ticket</button></section><?php endforeach; ?></div><?php endforeach; ?>
<script type="application/json" id="formatting-rules"><?= json_encode($rules,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?></script>
